import java.util.*;

public class ComparatorExample {
    private String prefix = "Customer";

    public void demonstrateDifference() {
        List<String> names = List.of("Alice", "Bob", "Charlie");

        // Lambda: 'this' refers to ComparatorExample instance
        names.sort((a, b) -> {
            System.out.println(this.prefix); // prints "Customer"
            return a.compareTo(b);
        });

        // Anonymous class: 'this' refers to the Comparator instance
        names.sort(new Comparator<String>() {
            private int callCount = 0; // can have instance state

            @Override
            public int compare(String a, String b) {
                callCount++;
                // 'this.callCount' refers to this Comparator's field
                // ComparatorExample.this.prefix for outer class
                return a.compareTo(b);
            }
        });
    }
}

import java.util.*;
import java.util.stream.*;

record Product(String name, double price, String category) {}

class ProductService {
    private final List<Product> inventory;

    public ProductService(List<Product> inventory) {
        this.inventory = inventory;
    }

    // Combines streams, lambdas, Optional, and method references
    public Optional<Double> findCheapestInCategory(String category) {
        return inventory.stream()                           // Stream API
                .filter(p -> p.category().equals(category)) // Lambda expression
                .map(Product::price)                        // Method reference
                .min(Double::compareTo);                    // Method reference + Optional
    }

    // Default methods let Collection interface have stream() method
    public Map<String, List<Product>> groupByCategory() {
        return inventory.stream()
                .collect(Collectors.groupingBy(Product::category));
    }
}
